  assertEquals("IN_PROGRESS",detail(h.a,ticket).get("status"));try(var c=files.ticketDb(false)){assertEquals(1,h.scalar(c,"SELECT COUNT(*) FROM ticket_processing_record WHERE ticket_id=? AND type='ASSIGNMENT-ACCEPT'",ticket));assertEquals(1,h.scalar(c,"SELECT COUNT(*) FROM ticket_action_operation WHERE operation_id=?",op));assertEquals(1,h.scalar(c,"SELECT COUNT(*) FROM ticket_audit WHERE operation_id=?",op));}
